#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;

int add(int x, int y) {
    x += y;
    return x >= MOD ? x - MOD : x;
}

int sub(int x, int y) {
    return x >= y ? x - y : x + MOD - y;
}

long long mul(long long x, long long y) {
    return x * y % MOD;
}

int modPow(int b, int e) {
    int r = 1;
    while (e) {
        if (e & 1) r = mul(r, b);
        b = mul(b, b);
        e >>= 1;
    }
    return r;
}

int n;
int p[8][8];
int g[8][8];
int mask3[7][7][7];
int fullMask;
int dp[1048576];
int ans;

bool valid(int a, int b, int c) {
    int vals[4] = {0, a, b, c};
    int idx[4] = {0, 1, 2, 3};
    do {
        bool ok = true;
        for (int i = 1; i <= 3; ++i) {
            if (!g[idx[i]][vals[i]]) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    } while (next_permutation(idx + 1, idx + 4));
    return false;
}

void dfs1(int cur, int r, int c) {
    if (!cur) return;
    if (r == 4) {
        bool used[7] = {false, true, true, true, true, true, true};
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (valid(i, j, k)) {
                        used[i] = used[j] = used[k] = false;
                        int x = -1, y = -1, z = -1;
                        for (int l = 1; l <= 6; ++l) {
                            if (!used[l]) {
                                if (x == -1) x = l;
                                else if (y == -1) y = l;
                                else z = l;
                            }
                        }
                        used[i] = used[j] = used[k] = true;
                        if (z != -1) state |= mask3[x][y][z];
                    }
                }
            }
        }
        dp[state] = add(dp[state], cur);
        return;
    }
    g[r][c] = 1;
    int nxt = mul(cur, p[r][c]);
    if (c == 6) dfs1(nxt, r + 1, 1);
    else dfs1(nxt, r, c + 1);
    g[r][c] = 0;
    nxt = mul(cur, sub(1, p[r][c]));
    if (c == 6) dfs1(nxt, r + 1, 1);
    else dfs1(nxt, r, c + 1);
}

void dfs2(int cur, int r, int c) {
    if (!cur) return;
    if (r == 7) {
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (valid(i, j, k)) state |= mask3[i][j][k];
                }
            }
        }
        ans = add(ans, mul(cur, dp[fullMask ^ state]));
        return;
    }
    g[r - 3][c] = 1;
    int nxt = mul(cur, p[r][c]);
    if (c == 6) dfs2(nxt, r + 1, 1);
    else dfs2(nxt, r, c + 1);
    g[r - 3][c] = 0;
    nxt = mul(cur, sub(1, p[r][c]));
    if (c == 6) dfs2(nxt, r + 1, 1);
    else dfs2(nxt, r, c + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    int inv100 = modPow(100, MOD - 2);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            int x; cin >> x;
            p[i][j] = mul(x, inv100);
        }
    }
    for (int i = n + 1; i <= 6; ++i) p[i][i] = 1;
    int cnt = 0;
    for (int i = 1; i <= 6; ++i) {
        for (int j = i + 1; j <= 6; ++j) {
            for (int k = j + 1; k <= 6; ++k) {
                mask3[i][j][k] = 1 << cnt;
                ++cnt;
            }
        }
    }
    fullMask = (1 << cnt) - 1;
    dfs1(1, 1, 1);
    int total = 1 << cnt;
    for (int b = 0; b < cnt; ++b) {
        for (int m = 0; m < total; ++m) {
            if (m & (1 << b)) {
                dp[m] = add(dp[m], dp[m ^ (1 << b)]);
            }
        }
    }
    ans = 0;
    dfs2(1, 4, 1);
    ans = sub(1, ans);
    cout << ans << '\n';
    return 0;
}
